(ns fastmath.ml.regression-test
  (:require [fastmath.ml.regression :as sut]
            [clojure.test :as t]
            [fastmath.core :as m]
            [clojure.pprint]
            [fastmath.vector :as v]
            [fastmath.matrix :as mat]
            [fastmath.ml.regression.contrast :as contrast]
            [clojure.edn :as edn]
            [clojure.java.io :as io]))

;; §2.2: shared, memoized EDN reference loader -- all R-fitted reference
;; values live in `test/resources/regression/*_reference.edn` (generated by
;; `fastmath.dev.regression-ref-gen`), so no live R session is needed to run
;; this test suite.

(def ^:private load-ref
  "Load and parse one `test/resources/regression/<name>_reference.edn` file.
  Memoized: each file is read and parsed at most once per test run,
  regardless of how many deftests/calls reference it."
  (memoize
   (fn [name]
     (-> (str "regression/" name "_reference.edn")
         io/resource
         slurp
         edn/read-string))))

;; §2.3: `col` is a raw categorical column (a seq of keywords); `values` are
;; the non-reference levels to build 0/1 columns for, matching the original
;; tablecloth `one-hot`'s calling convention. The reference level is
;; whichever level of `col` is not in `values`. Delegates to `contrast/dummy`;
;; duplicated (not shared) with the generator's own copy, per §4.

(defn- one-hot
  [col values]
  (let [levels (distinct col)
        reference (first (remove (set values) levels))
        coding (contrast/dummy (cons reference values))
        columns (apply map vector (map (:mapping coding) col))]
    (zipmap values columns)))

;; §2.3 extension: `col1`/`col2` are raw categorical columns. Reproduces the
;; original tablecloth `mult-columns`' exact column order and default
;; (first-appearance, sort1?/sort2?=false) reference-level convention.

(defn- mult-columns
  [col1 col2]
  (let [cs1 (vec (rest (distinct col1)))
        cs2 (vec (rest (distinct col2)))
        oh1 (one-hot col1 cs1)
        oh2 (one-hot col2 cs2)
        onehot1-cols (map oh1 cs1)
        onehot2-cols (map oh2 cs2)
        interactions (for [c2 cs2 c1 cs1] (mapv * (oh1 c1) (oh2 c2)))]
    {:cs1 cs1 :cs2 cs2 :xss (apply map vector (concat onehot1-cols onehot2-cols interactions))}))

;; §2.4: `col` is a raw numeric column; returns the first `n` columns of
;; `v/orthonormal-polynomials` (degree 1..n, R `poly()`'s own convention --
;; no degree-0/constant column). Duplicated (not shared) with the
;; generator's own copy, per §4.

(defn- add-poly
  [col n]
  (vec (take n (v/orthonormal-polynomials (seq col)))))

;; §3.1: named comparators, fine-grained -- each performs one `t/is` per field.
;; Shared between LM and GLM (identical shape on both sides):

(defn- check-coefficients
  "3.1.1. `coefs` = (:coefficients lm-or-glm), a seq of per-coefficient maps.
  `ref` = {:estimate [...] :stderr [...] :t-value|:z-value [...] :p-value [...]}.
  Reads whichever of :t-value/:z-value `ref` carries."
  [coefs ref]
  (t/is (v/delta-eq (map :estimate coefs) (:estimate ref)))
  (t/is (v/delta-eq (map :stderr coefs) (:stderr ref)))
  (let [stat-key (if (contains? ref :t-value) :t-value :z-value)]
    (t/is (v/delta-eq (map stat-key coefs) (stat-key ref))))
  (t/is (v/delta-eq (map :p-value coefs) (:p-value ref))))

(defn- check-xtxinv
  "3.1.2."
  [xtxinv ref]
  (t/is (v/delta-eq (mat/mat->seq xtxinv) ref)))

(defn- check-correlation
  "3.1.3. `correlation` = (:correlation analysis), a matrix; `ref` is flat."
  [correlation ref]
  (t/is (v/delta-eq (flatten correlation) ref)))

(defn- check-leverage
  "3.1.4."
  [leverage ref]
  (t/is (v/delta-eq (:hat leverage) (:hat ref)))
  (t/is (v/delta-eq (:sigmas leverage) (:sigmas ref)))
  (t/is (v/delta-eq (flatten (:coefficients leverage)) (:coefficients ref))))

(defn- check-influence
  "3.1.5. Optional `cooks-tol` (GLM uses 1e-5, LM uses the default)."
  ([influence ref] (check-influence influence ref nil))
  ([influence ref cooks-tol]
   (t/is (if cooks-tol
           (v/delta-eq (:cooks-distance influence) (:cooks-distance ref) cooks-tol)
           (v/delta-eq (:cooks-distance influence) (:cooks-distance ref))))
   (t/is (v/delta-eq (:dffits influence) (:dffits ref)))
   (t/is (v/delta-eq (:covratio influence) (:covratio ref)))
   (t/is (v/delta-eq (flatten (:dfbetas influence)) (:dfbetas ref)))))

(defn- check-df
  "3.1.6. Key-presence tolerant: checks whichever keys `ref` carries
  (LM: :residual/:model, GLM: :residual/:null)."
  [df ref]
  (doseq [k (keys ref)]
    (t/is (== (get df k) (get ref k)))))

(defn- check-ll
  "3.1.7. Key-presence tolerant (LM carries extra :aic-rss/:bic-rss)."
  [ll ref]
  (doseq [k (keys ref)]
    (t/is (m/delta-eq (get ll k) (get ref k)))))

;; LM-specific:

(defn- check-residuals-lm
  "3.1.8."
  [residuals ref]
  (t/is (v/delta-eq (:raw residuals) (:raw ref)))
  (t/is (v/delta-eq (:weighted residuals) (:weighted ref))))

(defn- check-fit-lm
  "3.1.9."
  [lm ref]
  (t/is (v/delta-eq (:fitted lm) (:fitted ref)))
  (t/is (m/delta-eq (:sigma lm) (:sigma ref)))
  (t/is (m/delta-eq (:sigma2 lm) (:sigma2 ref)))
  (t/is (m/delta-eq (:r-squared lm) (:r-squared ref)))
  (t/is (m/delta-eq (:adjusted-r-squared lm) (:adjusted-r-squared ref)))
  (t/is (m/delta-eq (:f-statistic lm) (:f-statistic ref))))

(defn- check-normality
  "3.1.10."
  [normality ref]
  (t/is (m/delta-eq (:skewness normality) (:skewness ref)))
  (t/is (m/delta-eq (:kurtosis normality) (:kurtosis ref)))
  (t/is (m/delta-eq (get-in normality [:durbin-watson :raw]) (:durbin-watson ref))))

(defn- check-analysis-residuals-lm
  "3.1.11."
  [residuals ref]
  (t/is (v/delta-eq (:standardized residuals) (:standardized ref)))
  (t/is (v/delta-eq (:studentized residuals) (:studentized ref))))

(def ys [1 2.1 3.2 4 4.9 5.5 10 7 8.1 8.7])
(def nys (v/normalize ys))
(def xss-1 '(-0.5 -1 -2 -3 -4 -5 -6 -7 -8 -9))
(def xss-2 '(1 2 0 2 1 0 1 2 0 2))
(def xss-3 (v/emult xss-1 xss-2))
(def xss (map vector xss-1 xss-2 xss-3))
(def weights [2 1 2 1 2 1 2 1 2 1])
(def offset (range 10))

(defn- lm-tests
  "§3.2. `ref-block` is an already-resolved {:model :analysis} map (the
  deftest call site owns loading and, for multi-call files, sub-key
  selection -- decouples this fn from I/O)."
  ([ys xss ref-block] (lm-tests ys xss nil ref-block))
  ([ys xss options ref-block]
   (let [lm (sut/lm ys xss options)
         analysis (sut/analysis lm)]
     (t/is (m/delta-eq (:intercept lm) (get-in ref-block [:model :intercept])))
     (t/is (v/delta-eq (:beta lm) (get-in ref-block [:model :beta])))
     (check-coefficients (:coefficients lm) (get-in ref-block [:model :coefficients]))
     (check-xtxinv (:xtxinv lm) (get-in ref-block [:model :xtxinv]))
     (check-df (:df lm) (get-in ref-block [:model :df]))
     (check-ll (:ll lm) (get-in ref-block [:model :ll]))
     (check-fit-lm lm (:model ref-block))
     (check-residuals-lm (:residuals lm) (get-in ref-block [:model :residuals]))
     (check-correlation (:correlation analysis) (get-in ref-block [:analysis :correlation]))
     (check-normality (:normality analysis) (get-in ref-block [:analysis :normality]))
     (check-analysis-residuals-lm (:residuals analysis) (get-in ref-block [:analysis :residuals]))
     (check-leverage (:leverage analysis) (get-in ref-block [:analysis :leverage]))
     (check-influence (:influence analysis) (get-in ref-block [:analysis :influence])))))

(t/deftest basic-weights-intercept
  (lm-tests ys xss {:weights weights} (load-ref "basic-weights-intercept")))

(t/deftest basic-weights-intercept-transformer
  (lm-tests ys xss {:weights weights :transformer (fn [[a b c]] [(m/exp a) a b c])}
                (load-ref "basic-weights-intercept-transformer")))

(t/deftest basic-weights-intercept-offset
  (lm-tests ys xss {:weights weights :offset offset} (load-ref "basic-weights-intercept-offset")))

(t/deftest basic-weights-no-intercept
  (lm-tests ys xss {:weights weights :intercept? false} (load-ref "basic-weights-no-intercept")))

(t/deftest basic-weights-no-intercept-offset
  (lm-tests ys xss {:weights weights :intercept? false :offset offset}
                (load-ref "basic-weights-no-intercept-offset")))

(t/deftest basic-no-weights-intercept
  (lm-tests ys xss (load-ref "basic-no-weights-intercept")))

(t/deftest basic-no-weights-intercept-offset
  (lm-tests ys xss {:offset offset} (load-ref "basic-no-weights-intercept-offset")))

(t/deftest basic-no-weights-no-intercept
  (lm-tests ys xss {:intercept? false} (load-ref "basic-no-weights-no-intercept")))

(t/deftest basic-no-weights-no-intercept-offset
  (lm-tests ys xss {:intercept? false :offset offset} (load-ref "basic-no-weights-no-intercept-offset")))

;; GLM-specific comparators (§3.1.12-3.1.16, 3.1.19). `check-coefficients`,
;; `check-xtxinv`, `check-correlation`, `check-leverage`, `check-influence`,
;; `check-df`, `check-ll` above are already shared with LM.

(defn- check-residuals-glm
  "3.1.12."
  [residuals ref]
  (t/is (v/delta-eq (:working residuals) (:working ref) 1.0e-5))
  (t/is (v/delta-eq (:deviance residuals) (:deviance ref)))
  (t/is (v/delta-eq (:pearson residuals) (:pearson ref)))
  (t/is (v/delta-eq (:raw residuals) (:raw ref) 1.0e-4)))

(defn- check-fit-glm
  "3.1.13. :deviance :null is deliberately NOT checked here -- the original
  glm-tests only compares it when :compare-deviance-null? is explicitly true
  (default false), so that gate lives at the glm-tests call site instead."
  [glm ref]
  (t/is (v/delta-eq (:fitted glm) (:fitted ref) 1.0e-4))
  (t/is (m/delta-eq (:dispersion glm) (:dispersion ref)))
  (t/is (m/delta-eq (get-in glm [:deviance :residual]) (get-in ref [:deviance :residual]))))

(defn- check-weights
  "3.1.14."
  [weights ref]
  (t/is (v/delta-eq (:weights weights) (:weights ref)))
  (t/is (v/delta-eq (:initial weights) (:initial ref))))

(defn- check-analysis-residuals-glm
  "3.1.15."
  [residuals ref]
  (t/is (v/delta-eq (:studentized residuals) (:studentized ref)))
  (t/is (v/delta-eq (get-in residuals [:standardized :deviance]) (get-in ref [:standardized :deviance])))
  (t/is (v/delta-eq (get-in residuals [:standardized :pearson]) (get-in ref [:standardized :pearson]))))

(defn- check-dose
  "3.1.16."
  [dose ref]
  (t/is (m/delta-eq (:dose dose) (:dose ref)))
  (t/is (m/delta-eq (:stderr dose) (:stderr ref))))

(defn- check-quantile-residuals
  "3.1.19."
  [qres ref]
  (t/is (v/delta-eq qres ref)))

(defn- glm-tests
  "§3.3. `ref-block` is an already-resolved {:model :analysis :extra} map.
  Dose is checked whenever fastmath's own fitted model has >1 coefficient AND
  the reference carries a (non-error) dose block -- mirrors the generator's
  own `(when (> (count (:coefficients model)) 1) ...)` gate exactly (fixing
  the original R-based `glm-tests`' `:coefficeints` typo, which had made its
  own dose comparison permanently vacuous)."
  ([ys xss ref-block] (glm-tests ys xss nil ref-block))
  ([ys xss options ref-block]
   (let [glm (sut/glm ys xss (merge {:epsilon 1.0e-16 :max-iters 100} options))
         analysis (sut/analysis glm)]
     (t/is (m/delta-eq (:intercept glm) (get-in ref-block [:model :intercept])))
     (t/is (v/delta-eq (:beta glm) (get-in ref-block [:model :beta])))
     (check-coefficients (:coefficients glm) (get-in ref-block [:model :coefficients]))
     (check-xtxinv (:xtxinv glm) (get-in ref-block [:model :xtxinv]))
     (check-df (:df glm) (get-in ref-block [:model :df]))
     (when-not (:no-ll? options)
       (check-ll (:ll glm) (get-in ref-block [:model :ll])))
     (check-fit-glm glm (:model ref-block))
     (when (:compare-deviance-null? options)
       (t/is (m/delta-eq (get-in glm [:deviance :null]) (get-in ref-block [:model :deviance :null]))))
     (check-residuals-glm (:residuals glm) (get-in ref-block [:model :residuals]))
     (check-weights (:weights glm) (get-in ref-block [:model :weights]))
     (when-not (:no-analysis? options)
       (check-correlation (:correlation analysis) (get-in ref-block [:analysis :correlation]))
       (check-analysis-residuals-glm (:residuals analysis) (get-in ref-block [:analysis :residuals]))
       (check-leverage (:leverage analysis) (get-in ref-block [:analysis :leverage]))
       (check-influence (:influence analysis) (get-in ref-block [:analysis :influence]) 1.0e-5))
     (when (> (count (:coefficients glm)) 1)
       (let [dose-ref (get-in ref-block [:extra :dose])]
         (when (and dose-ref (not (:error dose-ref)))
           (check-dose (sut/dose glm) dose-ref))))
     (when-let [qres-ref (get-in ref-block [:extra :quantile-residuals])]
       (check-quantile-residuals (sut/quantile-residuals glm) qres-ref)))))

(t/deftest dummy-data
  (let [ref (load-ref "dummy-data")]
    (glm-tests nys xss {:weights weights :family :binomial} (:call-0 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :probit} (:call-1 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :cloglog} (:call-2 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :log} (:call-3 ref))
    (glm-tests nys xss {:family :binomial} (:call-4 ref))
    (glm-tests nys xss {:family :binomial :link :probit} (:call-5 ref))
    (glm-tests nys xss {:family :binomial :link :cloglog} (:call-6 ref))
    (glm-tests nys xss {:family :binomial :link :log} (:call-7 ref))
    (glm-tests nys xss {:weights weights :family :binomial :intercept? false} (:call-8 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :probit :intercept? false} (:call-9 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :cloglog :intercept? false} (:call-10 ref))
    (glm-tests nys xss {:family :binomial :intercept? false} (:call-11 ref))
    (glm-tests nys xss {:family :binomial :link :probit :intercept? false} (:call-12 ref))
    (glm-tests nys xss {:family :binomial :link :cloglog :intercept? false} (:call-13 ref))
    (glm-tests nys xss {:family :binomial :transformer (fn [[a b c]] [(m/exp a) a b c])} (:call-14 ref))))

(t/deftest gaussian-glm
  (let [ref (load-ref "gaussian-glm")]
    (glm-tests ys xss {:weights weights} (:call-0 ref))
    (glm-tests ys xss {:weights weights :offset offset} (:call-1 ref))
    (glm-tests ys xss {:weights weights :intercept? false} (:call-2 ref))
    (glm-tests ys xss {:weights weights :intercept? false :offset offset} (:call-3 ref))
    (glm-tests ys xss nil (:call-4 ref))
    (glm-tests ys xss {:offset offset} (:call-5 ref))
    (glm-tests ys xss {:intercept? false} (:call-6 ref))
    (glm-tests ys xss {:intercept? false :offset offset} (:call-7 ref))))

(t/deftest gestation-data
  (let [ref (load-ref "gestation-data")
        {:keys [Weight Age Births]} (get-in ref [:inputs :columns])]
    (lm-tests Weight Age {:weights Births} (:call-0 ref))
    (lm-tests Weight Age (:call-1 ref))))

(t/deftest lungcap-data
  (let [ref (load-ref "lungcap-data")
        {:keys [FEV Age Ht Gender Smoke]} (get-in ref [:inputs :columns])
        logfev (mapv m/log FEV)
        gender-numeric (mapv #(if (= % :F) 0.0 1.0) Gender)
        {gender-f :F gender-m :M} (one-hot Gender [:F :M])
        ht-smoke (mapv * Ht Smoke)]
    (lm-tests logfev (map vector Age Ht gender-numeric Smoke) (:call-0 ref))
    (lm-tests logfev (map vector Age Ht gender-f gender-m Smoke) {:intercept? false} (:call-1 ref))
    (lm-tests logfev (map vector Ht gender-numeric Smoke) (:call-2 ref))
    (lm-tests logfev (map vector gender-numeric Smoke) (:call-3 ref))
    (lm-tests logfev (map vector Age Smoke) (:call-4 ref))
    (lm-tests logfev (map vector Ht Smoke) (:call-5 ref))
    (lm-tests logfev (map vector Ht Smoke ht-smoke) (:call-6 ref))))

(t/deftest dental-data
  (let [ref (load-ref "dental-data")
        {:keys [DMFT Sugar Indus]} (get-in ref [:inputs :columns])
        indus-bin (mapv #(if (= % :Ind) 0.0 1.0) Indus)
        sugar-indus (mapv * Sugar indus-bin)]
    (lm-tests DMFT (map vector Sugar indus-bin sugar-indus) ref)))

(t/deftest cheese-data
  (let [ref (load-ref "cheese-data")
        {:keys [Taste Acetic H2S Lactic]} (get-in ref [:inputs :columns])
        lH2S (mapv m/log H2S)
        acetic-lH2S (mapv * Acetic lH2S)
        acetic-lactic (mapv * Acetic Lactic)
        lH2S-lactic (mapv * lH2S Lactic)
        triple (mapv * Acetic lH2S Lactic)]
    (lm-tests Taste (map vector Acetic lH2S Lactic acetic-lH2S acetic-lactic lH2S-lactic triple) ref)))

(t/deftest turbunes-data
  (let [ref (load-ref "turbunes-data")
        {:keys [Fissures Turbines Hours]} (get-in ref [:inputs :columns])
        ratio (mapv / Fissures Turbines)
        turb-fiss-diff (mapv - Turbines Fissures)]
    (glm-tests ratio Hours {:family :binomial :weights Turbines} (:call-0 ref))
    (glm-tests (mapv vector Fissures turb-fiss-diff) Hours {:family :binomial} (:call-1 ref))
    (glm-tests ratio Hours {:family :binomial :weights Turbines :link :probit} (:call-2 ref))
    (glm-tests ratio Hours {:family :binomial :weights Turbines :link :cloglog} (:call-3 ref))))

(t/deftest germ-data
  (let [ref (load-ref "germ-data")
        {:keys [Germ Total Seeds Extract]} (get-in ref [:inputs :columns])
        seeds-oa75 (mapv #(if (= % :OA75) 1.0 0.0) Seeds)
        extract-cucumber (mapv #(if (= % :Cucumber) 1.0 0.0) Extract)
        es (mapv * extract-cucumber seeds-oa75)
        ratio (mapv / Germ Total)]
    (glm-tests ratio (mapv vector seeds-oa75 extract-cucumber)
                   {:family :binomial :weights Total} (:call-0 ref))
    (glm-tests ratio (mapv vector seeds-oa75 extract-cucumber es)
                   {:family :binomial :weights Total} (:call-1 ref))
    (glm-tests ratio (mapv vector seeds-oa75 extract-cucumber es)
                   {:family :quasi-binomial :weights Total :no-ll? true} (:call-2 ref))))

(t/deftest mammary-data
  (let [ref (load-ref "mammary-data")
        columns (get-in ref [:inputs :columns])
        n-outgrowths (:N.Outgrowths columns)
        n-assays (:N.Assays columns)
        n-cells (:N.Cells columns)
        ratio (mapv / n-outgrowths n-assays)
        lncells (mapv m/log n-cells)]

    ;; only intercept and offset
    (glm-tests ratio :intercept {:family :binomial :link :cloglog
                                     :weights n-assays :offset lncells}
                   (:call-0 ref))

    ;; intercept, offset, data point
    (glm-tests ratio n-outgrowths {:family :binomial :link :cloglog
                                       :weights n-assays :offset lncells}
                   (:call-1 ref))

    ;; no intercept, offset, data point
    (glm-tests ratio n-outgrowths {:family :binomial :link :cloglog
                                       :weights n-assays :offset lncells
                                       :intercept? false :compare-deviance-null? false}
                   (:call-2 ref))

    (glm-tests ratio lncells {:family :binomial :link :cloglog :weights n-assays}
                   (:call-3 ref))))

(t/deftest deposit-data
  (let [ref (load-ref "deposit-data")
        {:keys [Killed Number Deposit Insecticide]} (get-in ref [:inputs :columns])
        ratio (mapv / Killed Number)
        logdep (mapv m/log Deposit)
        {ins-a :A ins-b :B ins-c :C} (one-hot Insecticide [:A :B :C])
        [logdep-poly0 logdep-poly1] (add-poly logdep 2)
        model (sut/glm ratio (map vector Deposit ins-b ins-c) {:family :binomial :weights Number})
        model2 (sut/glm ratio (map vector Deposit ins-a ins-b ins-c)
                        {:family :binomial :weights Number :intercept? false})
        newdata (get-in ref [:extra :newdata])]
    (glm-tests ratio (map vector Deposit ins-b ins-c) {:family :binomial :weights Number} (:call-0 ref))
    (glm-tests ratio (map vector Deposit ins-a ins-b ins-c)
                   {:family :binomial :weights Number :intercept? false} (:call-1 ref))
    (glm-tests ratio (map vector logdep ins-a ins-b ins-c)
                   {:family :binomial :weights Number :intercept? false} (:call-2 ref))
    (t/is (v/delta-eq (map model (map vector newdata (repeat 0) (repeat 0)))
                      (get-in ref [:extra :predict-a])))
    (t/is (v/delta-eq (map model (map vector newdata (repeat 1) (repeat 0)))
                      (get-in ref [:extra :predict-b])))
    (t/is (v/delta-eq (map model (map vector newdata (repeat 0) (repeat 1)))
                      (get-in ref [:extra :predict-c])))
    (t/are [id v] (v/delta-eq (:dose (sut/dose model2 0.5 id 0)) v)
      1 5.099708
      2 4.514714
      3 0.8443372)
    (glm-tests ratio (map vector logdep-poly0 logdep-poly1 ins-b ins-c)
                   {:family :binomial :weights Number} (:call-3 ref))))

;; poisson

(t/deftest danishlc-data
  (let [ref (load-ref "danishlc-data")
        {:keys [Cases Pop Age City AgeNum]} (get-in ref [:inputs :columns])
        loffset (v/log (seq Pop))
        {:keys [xss]} (mult-columns City Age)
        {age-5559 :55-59 age-6064 :60-64 age-6569 :65-69 age-7074 :70-74 age-gt74 :>74}
        (one-hot Age [:55-59 :60-64 :65-69 :70-74 :>74])
        age-xss (map vector age-5559 age-6064 age-6569 age-7074 age-gt74)
        [agenum-poly0 agenum-poly1] (add-poly AgeNum 2)]
    ;; df = 0
    (glm-tests Cases xss {:family :poisson :offset loffset :no-analysis? true} (:call-0 ref))
    (glm-tests Cases age-xss {:family :poisson :offset loffset} (:call-1 ref))
    (glm-tests Cases AgeNum {:family :poisson :offset loffset} (:call-2 ref))
    (glm-tests Cases (map vector agenum-poly0 agenum-poly1) {:family :poisson :offset loffset} (:call-3 ref))))


(t/deftest counts2x2-data
  (let [ref (load-ref "counts2x2-data")
        {:keys [Counts Att Inc]} (get-in ref [:inputs :columns])
        {att-against :Against} (one-hot Att [:Against])
        {inc-low :Low} (one-hot Inc [:Low])
        att-inc-low (mapv * att-against inc-low)]
    (glm-tests Counts (map vector att-against inc-low)
                   {:family :poisson :no-analysis? true} (:call-0 ref))
    (glm-tests Counts (map vector att-against inc-low att-inc-low)
                   {:family :poisson :no-analysis? true} (:call-1 ref))
    (glm-tests att-against inc-low {:family :binomial :weights Counts} (:call-2 ref))))

(t/deftest kstones-data
  (let [ref (load-ref "kstones-data")
        {:keys [Counts Size Method Outcome]} (get-in ref [:inputs :columns])
        {size-small :Small} (one-hot Size [:Small])
        {method-b :B} (one-hot Method [:B])
        {outcome-success :Success} (one-hot Outcome [:Success])
        size-method (mapv * size-small method-b)
        size-outcome (mapv * size-small outcome-success)
        method-outcome (mapv * method-b outcome-success)
        size-method-outcome (mapv * size-small method-b outcome-success)]
    (glm-tests Counts (map vector size-small method-b outcome-success)
                   {:family :poisson} (:call-0 ref))
    (glm-tests Counts (map vector size-small method-b outcome-success size-method)
                   {:family :poisson} (:call-1 ref))
    (glm-tests Counts (map vector size-small outcome-success method-b size-outcome)
                   {:family :poisson} (:call-2 ref))
    (glm-tests Counts (map vector outcome-success method-b size-small method-outcome)
                   {:family :poisson} (:call-3 ref))
    (glm-tests Counts (map vector size-small method-b outcome-success size-method size-outcome)
                   {:family :poisson} (:call-4 ref))
    (glm-tests Counts (map vector method-b outcome-success size-small method-outcome size-method)
                   {:family :poisson} (:call-5 ref))
    (glm-tests Counts (map vector outcome-success method-b size-small method-outcome size-outcome)
                   {:family :poisson} (:call-6 ref))
    (glm-tests Counts (map vector size-small method-b outcome-success size-method size-outcome method-outcome)
                   {:family :poisson :no-analysis? true} (:call-7 ref))
    (glm-tests Counts (map vector size-small method-b outcome-success size-method size-outcome method-outcome
                                size-method-outcome)
                   {:family :poisson :no-analysis? true} (:call-8 ref))
    (glm-tests outcome-success (map vector size-small method-b size-method)
                   {:family :binomial :weights Counts} (:call-9 ref))))

(t/deftest pock-data
  (let [ref (load-ref "pock-data")
