    (glm-tests Count l2dilution {:family :poisson} (:call-0 ref))
    (glm-tests Count l2dilution {:family :quasi-poisson :no-ll? true} (:call-1 ref))
    (glm-tests Count l2dilution {:family :nbinomial :nbinomial-theta 9.892894299757403} (:call-2 ref))
    (t/is (m/delta-eq (get-in ref [:extra :nbinomial-theta])
                      (:nbinomial-theta (sut/glm-nbinomial Count l2dilution))))))

(t/deftest hcrabs-data
  (let [ref (load-ref "hcrabs-data")
        {:keys [Sat Wt Width Spine Col]} (get-in ref [:inputs :columns])
        logwt (mapv m/log Wt)
        logwidth (mapv m/log Width)
        {spine-noneok :NoneOK spine-oneok :OneOK} (one-hot Spine [:NoneOK :OneOK])
        {col-dm :DM col-lm :LM col-m :M} (one-hot Col [:DM :LM :M])
        full-xss (map vector logwt logwidth spine-noneok spine-oneok col-dm col-lm col-m)]
    (glm-tests Sat full-xss {:family :quasi-poisson :no-ll? true} (:call-0 ref))
    (glm-tests Sat logwt {:family :quasi-poisson :no-ll? true} (:call-1 ref))
    (glm-tests Sat logwt {:family :nbinomial :nbinomial-theta 0.9580286019527684} (:call-2 ref))
    (t/is (m/delta-eq (get-in ref [:extra :nbinomial-theta])
                      (:nbinomial-theta (sut/glm-nbinomial Sat logwt))))))

(t/deftest lime-data
  (let [ref (load-ref "lime-data")
        {:keys [Foliage DBH Origin]} (get-in ref [:inputs :columns])
        logdbh (mapv m/log DBH)
        {origin-natural :Natural origin-planted :Planted} (one-hot Origin [:Natural :Planted])
        origin-natural-logdbh (mapv * origin-natural logdbh)
        origin-planted-logdbh (mapv * origin-planted logdbh)
        xss (map vector origin-natural origin-planted logdbh origin-natural-logdbh origin-planted-logdbh)]
    (glm-tests Foliage xss {:family :gamma :link :log} (:call-0 ref))
    (t/is (v/delta-eq (-> (sut/glm Foliage xss {:family :gamma :link :log})
                          (sut/quantile-residuals))
                      (get-in ref [:call-0 :extra :quantile-residuals]) 5.0e-3))
    (glm-tests Foliage xss {:family :inverse-gaussian :link :log} (:call-1 ref))))

(t/deftest perm-data
  (let [ref (load-ref "perm-data")
        {:keys [Perm Mach Day]} (get-in ref [:inputs :columns])
        {:keys [xss]} (mult-columns Mach Day)]
    (glm-tests Perm xss {:family :inverse-gaussian :link :log} ref)))

(t/deftest yieldden-data
  (let [ref (load-ref "yieldden-data")
        {:keys [YD Dens Var]} (get-in ref [:inputs :columns])
        rdens (mapv #(/ 1.0 %) Dens)
        {var2 :2 var3 :3} (one-hot Var [:2 :3])
        dens-var2 (mapv * Dens var2)
        dens-var3 (mapv * Dens var3)
        rdens-var2 (mapv * rdens var2)
        rdens-var3 (mapv * rdens var3)
        full-xss (map vector Dens rdens var2 var3 dens-var2 dens-var3 rdens-var2 rdens-var3)
        simple-xss (map vector Dens rdens var2 var3)]
    (glm-tests YD full-xss {:family :gamma :link :inverse} (:call-0 ref))
    (glm-tests YD simple-xss {:family :gamma :link :inverse} (:call-1 ref))
    (t/is (v/delta-eq (-> (sut/glm YD simple-xss {:family :inverse-gaussian})
                          (sut/quantile-residuals))
                      (get-in ref [:extra :quantile-residuals])))))


(t/deftest lm-simplest-case
  (t/testing "Daniel's case"
    (let [model (sut/lm [3 3 5 6] [[1 1] [2 1] [3 2] [4 2]])]
      (t/is (m/delta-eq 4.25 (model [1 2])))))
  (t/testing "1d prediction"
    (let [model (sut/lm [3 3 5 6] [1 2 3 4])]
      (t/is (m/delta-eq 2.6 (model 1)))
      (t/is (m/delta-eq 2.6 (model [1])))))
  (t/testing "1d prediction with offset"
    (let [model (sut/lm [3 3 5 6] [1 2 3 4] {:offset [11 12 13 14]})]
      (t/is (m/delta-eq 2.6 (model [11 1])))
      (t/testing "wrong number of entries on input"
        (t/is (= {:offset? true :expected 1 :received 0} (try (model 1) (catch clojure.lang.ExceptionInfo e (ex-data e)))))
        (t/is (= {:offset? true :expected 1 :received 0} (try (model [1]) (catch clojure.lang.ExceptionInfo e (ex-data e)))))
        (t/is (= {:offset? true :expected 1 :received 2} (try (model [1 2 3]) (catch clojure.lang.ExceptionInfo e (ex-data e)))))))))

